import string

def _t():

    class CheckAllUsedFormatter(string.Formatter):

        def check_unused_args(self, used_args, args, kwargs):
            unused_args = set(kwargs.keys())
            unused_args.update(range(0, len(args)))
            for arg in used_args:
                unused_args.remove(arg)
            if unused_args:
                raise ValueError('unused arguments')
    fmt = CheckAllUsedFormatter()
    assert fmt.format('{0}', 10) == '10', ('assertEqual', fmt.format('{0}', 10), '10')
    assert fmt.format('{0}{i}', 10, i=100) == '10100', ('assertEqual', fmt.format('{0}{i}', 10, i=100), '10100')
    assert fmt.format('{0}{i}{1}', 10, 20, i=100) == '1010020', ('assertEqual', fmt.format('{0}{i}{1}', 10, 20, i=100), '1010020')
